import json


def export_rows(rows: list[dict], fmt: str = "csv") -> str:
    if fmt == "csv":
        lines = ["id,name"]
        for row in rows:
            lines.append(f"{row['id']},{row['name']}")
        return "\n".join(lines) + "\n"
    if fmt == "json":
        return json.dumps(rows, ensure_ascii=False)
    raise ValueError(f"unsupported format: {fmt}")

